"""Static ZIP verification uses no extraction and compares exact generated bytes."""
import io
import json
from pathlib import Path
import stat
import unittest
import warnings
import zipfile

from scripts.creator_bundle import verify_bundle, MAX_ARCHIVE
from scripts.creator_project import read_spec
from scripts.creator_studio import export_zip

ROOT = Path(__file__).resolve().parents[1]


class BundleTests(unittest.TestCase):
    def setUp(self):
        self.spec = read_spec(ROOT / "projects" / "example.json")
        self.data = export_zip(self.spec)

    def rewrite(self, replacements=None, extra=(), remove=()):
        output = io.BytesIO()
        with zipfile.ZipFile(io.BytesIO(self.data)) as old, zipfile.ZipFile(output, "w") as new:
            for name in old.namelist():
                if name not in remove:
                    new.writestr(name, (replacements or {}).get(name, old.read(name)))
            for name, content in extra:
                new.writestr(name, content)
        return output.getvalue()

    def test_original_bundle_passes(self):
        report = verify_bundle(self.data)
        self.assertEqual(report["status"], "passed")
        self.assertEqual(report["pages"], 2)
        self.assertIn("index.html", report["files"])
        self.assertFalse(report["publication_ready"])
        self.assertEqual(len(report["archive_sha256"]), 64)

    def test_tamper_extra_and_missing_entries_rejected(self):
        for data in (
            self.rewrite({"site/index.html": b"changed"}),
            self.rewrite(extra=[("../outside.txt", b"never extract")]),
            self.rewrite(remove=["site/index.html"]),
            self.rewrite({"site/creator-manifest.json": b'{"version": 1}'}),
            self.rewrite({"project.json": b'{"version": 1, "version": 1}'}),
        ):
            with self.subTest(data_size=len(data)), self.assertRaises(ValueError):
                verify_bundle(data)

    def test_duplicate_and_special_entries_rejected(self):
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", UserWarning)
            duplicate = self.rewrite(extra=[("project.json", b"{}")])
        link = zipfile.ZipInfo("site/link")
        link.create_system = 3
        link.external_attr = (stat.S_IFLNK | 0o777) << 16
        for data in (duplicate, self.rewrite(extra=[(link, b"target")])):
            with self.assertRaises(ValueError):
                verify_bundle(data)

    def test_unapproved_drafts_only(self):
        spec = self.spec.copy()
        spec["review"] = {key: True for key in spec["review"]}
        with self.assertRaises(ValueError):
            verify_bundle(self.rewrite({"project.json": json.dumps(spec).encode()}))

    def test_invalid_and_oversized_archives(self):
        for data in (b"", b"not a zip", b"x" * (MAX_ARCHIVE + 1)):
            with self.assertRaises(ValueError):
                verify_bundle(data)


if __name__ == "__main__":
    unittest.main()
